{"content": "import socket, sys, time

class Conn:
    def __init__(self, host='robust', port=1337):
        self.s = socket.create_connection((host, port), 5)
        self.s.settimeout(3.0)
        self.buf = b''
    def recv_until(self, token, timeout=3.0):
        end = time.time() + timeout
        while token not in self.buf:
            if time.time() > end:
                raise TimeoutError(f'timeout waiting {token!r}, buf={self.buf!r}')
            try:
                d = self.s.recv(4096)
            except socket.timeout:
                raise TimeoutError(f'timeout waiting {token!r}, buf={self.buf!r}')
            if not d:
                raise EOFError(f'eof waiting {token!r}, buf={self.buf!r}')
            self.buf += d
        i = self.buf.index(token) + len(token)
        out, self.buf = self.buf[:i], self.buf[i:]
        return out
    def sendline(self, data):
        if isinstance(data, str):
            data = data.encode()
        self.s.sendall(data + b'\n')
    def close(self):
        self.s.close()

def genmac(msg_hex):
    c = Conn()
    c.recv_until(b'Enter your choice: ')
    c.sendline('2')
    c.recv_until(b'Enter message in hex: ')
    c.sendline(msg_hex)
    out = c.recv_until(b'Enter your choice: ')
    c.close()
    return out

if __name__ == '__main__':
    for n in [0,1,4,15,16,17,31,32,33,47,48,64]:
        msg = ('41'*n)
        try:
            out = genmac(msg)
        except Exception as e:
            out = repr(e).encode()
        print(n, out.decode('latin-1').replace('\n','|'))
