def session(steps):
    s = socket.create_connection(('robust', 1337), 5)
    s.settimeout(3.0)
    buf = b''
    out = b''
    def rd_until(tok, timeout=3.0):
        nonlocal buf, out
        end = time.time() + timeout
        while tok not in buf:
            if time.time() > end:
                return False
            try:
                d = s.recv(4096)
            except socket.timeout:
                return False
            if not d:
                return False
            buf += d
            out += d
        i = buf.index(tok) + len(tok)
        buf = buf[i:]
        return True
    for step in steps:
        if isinstance(step, str) and step.startswith('WAIT:'):
            if not rd_until(step[5:].encode()):
                break
        else:
            s.sendall(step.encode() + b'\n')
            time.sleep(0.15)
            try:
                d = s.recv(65536)
                if d:
                    out += d
            except socket.timeout:
                pass
    s.settimeout(1.0)
    for _ in range(20):
        try:
            d = s.recv(65536)
            if not d: break
            out += d
        except socket.timeout:
            break
    s.close()
    return out

tests = {
